\title{Cuaderno matemático}
\author{Estudiante}
\date{\today}

\begin{document}
\maketitle

\textbf{Enunciado.} Resuelve $2x+1=5$.

Restamos uno y dividimos entre dos:
\begin{align*}2x+1&=5\\2x&=4\\x&=2\end{align*}

Por tanto, $\boxed{x=2}$.
\begin{equation}2(2)+1=5\end{equation}
